import re
import json

def extract_log_parameters(log_text: str):
    """
    从包含大模型推理和工具调用的日志文本中，提取所需参数。
    
    参数:
        log_text (str): 包含日志内容的纯字符串输入
        
    返回:
        tuple: (original_query, masked_query, db_schema)
    """
    original_query = ""
    masked_query = ""
    db_schema = ""

    # 1. 提取 original_query
    # 匹配 entity_extract 的 arguments JSON，取第一次提取的原始问题
    entity_pattern = r'\{"name":\s*"entity_extract",\s*"arguments":\s*(\{.*?\})\}'
    entity_matches = re.findall(entity_pattern, log_text, re.DOTALL)
    
    if entity_matches:
        try:
            entity_args = json.loads(entity_matches[0])
            original_query = entity_args.get("query_to_extract", "")
        except json.JSONDecodeError as e:
            print(f"解析 original_query JSON 失败: {e}")

    # 2. 提取 masked_query 和 db_schema
    # 匹配 sql_generate 的 arguments JSON，取最后一次尝试（最接近最终结果的一次）
    sql_gen_pattern = r'\{"name":\s*"sql_generate",\s*"arguments":\s*(\{.*?\})\}'
    sql_gen_matches = re.findall(sql_gen_pattern, log_text, re.DOTALL)
    
    if sql_gen_matches:
        try:
            # 取列表最后一个元素 [-1]，即最后一次 sql_generate 尝试
            sql_args = json.loads(sql_gen_matches[-1]) 
            masked_query = sql_args.get("masked_query", "")
            db_schema = sql_args.get("masked_schema_str", "")
        except json.JSONDecodeError as e:
            print(f"解析 sql_generate JSON 失败: {e}")

    # 返回这三个提取到的字符串
    return original_query, masked_query, db_schema

